/**
 * Block Puzzle — zero-dep CSS bundler.
 *
 * Concatenates modular sources (see public/css/modules.json for the cascade order)
 * into public/styles.css. Feature folders: 00-base, 10-home, 20-board, 30-match;
 * public/css/styles-perf.css (graphics tiers) is always last.
 *
 *   node scripts/bundle-css.js
 *   node scripts/bundle-css.js --no-minify
 */
'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT = path.join(__dirname, '..');
const OUT = path.join(ROOT, 'public', 'styles.css');
const MINIFY = !process.argv.includes('--no-minify');

/** Cascade order lives in public/css/modules.json (single source of truth). */
const MODULES = JSON.parse(fs.readFileSync(path.join(ROOT, 'public', 'css', 'modules.json'), 'utf8')).modules;

function readVersion() {
  try {
    return JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8')).version || '0.0.0';
  } catch (_) {
    return '0.0.0';
  }
}

/** Strip comments and collapse excess whitespace (safe for this codebase). */
function lightMinifyCss(src) {
  let out = src.replace(/\/\*[\s\S]*?\*\//g, '');
  // A descendant combinator before a pseudo-class (`body :is(...)`, `.a :not(.b)`) is a *space*;
  // the whitespace collapsing below would turn it into a compound selector (`body:is(...)`)
  // and silently change what the rule matches. Make the implicit `*` explicit first.
  out = out.replace(/([^\s{};,(>+~:])\s+(:(?!:)[a-z-]+)/g, (m, prev, pseudo) => {
    // Only selector context: skip declarations such as `margin: 0`/`and (min-width :`
    return /^:(is|where|not|has|nth-[a-z-]+|first-child|last-child|first-of-type|last-of-type|only-child|hover|focus|focus-within|focus-visible|active|checked|disabled|enabled|empty)\b/.test(pseudo)
      ? prev + ' *' + pseudo : m;
  });
  // Collapse spaces/tabs around braces and semicolons (keep newlines lightly for debuggability)
  out = out.replace(/[ \t]+/g, ' ');
  out = out.replace(/\s*([{}:;,>])\s*/g, '$1');
  out = out.replace(/;}/g, '}');
  out = out.replace(/\n{2,}/g, '\n');
  out = out.trim() + '\n';
  return out;
}

function build() {
  const VERSION = readVersion();
  const parts = [];
  const included = [];

  for (const rel of MODULES) {
    const abs = path.join(ROOT, rel);
    if (!fs.existsSync(abs)) {
      console.warn('[bundle-css] missing', rel);
      continue;
    }
    let src = fs.readFileSync(abs, 'utf8').replace(/^\uFEFF/, '').replace(/\r\n/g, '\n');
    parts.push('/* ===== ' + rel + ' ===== */\n' + src.trim() + '\n');
    included.push(rel);
  }

  const bodyRaw = parts.join('\n');
  const body = MINIFY ? lightMinifyCss(bodyRaw) : bodyRaw;
  const hash = crypto.createHash('sha256').update(body).digest('hex').slice(0, 12);
  const banner =
    '/* =============================================================================\n' +
    '   Block Puzzle styles — v' + VERSION +
    (MINIFY ? ' (minified)' : '') + '\n' +
    '   Generated by scripts/bundle-css.js — DO NOT EDIT\n' +
    '   modules: ' + included.length + ' | sha256:' + hash + '\n' +
    '   Modular sources: public/css/{00-base,10-home,20-board,30-match}/ + styles-perf.css\n' +
    '   ============================================================================= */\n\n';

  const out = banner + body;
  fs.writeFileSync(OUT, out);
  console.log(
    '[bundle-css] OK v' + VERSION + ' hash=' + hash +
    ' modules=' + included.length +
    (MINIFY ? ' minified' : '') +
    ' bytes=' + Buffer.byteLength(out) +
    ' (raw ' + Buffer.byteLength(bodyRaw) + ')'
  );
  return { version: VERSION, hash, modules: included, bytes: Buffer.byteLength(out) };
}

if (require.main === module) {
  build();
}

module.exports = { build, MODULES, OUT };
